settings.css:
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600;700&family=Poppins:wght@400;500;600;700&display=swap');
@import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css');

#snooze-glossary{--c-coral:#F43357;--c-coral-hover:#D62646;--c-navy:#1F293B;--c-cream:#FAF7F4;--c-beige:#F2EDEA;--c-white:#fff;--c-sage:#7C8A98;--c-text:#161E2A;--c-muted:#64748B;--fb:'Poppins',sans-serif;--fh:'Playfair Display',serif;--shadow:0 2px 10px rgba(0,0,0,.06);font-family:var(--fb);color:var(--c-text);line-height:1.6;background:var(--c-cream);width:100%;overflow-x:hidden;isolation:isolate}
#snooze-glossary *,#snooze-glossary *::before,#snooze-glossary *::after{box-sizing:border-box}
#snooze-glossary h1,#snooze-glossary h2{font-family:var(--fh);color:var(--c-navy);line-height:1.2;margin:0}
#snooze-glossary a{text-decoration:none;transition:.2s ease}
#snooze-glossary .gl-hero{background:linear-gradient(180deg,var(--c-white),var(--c-cream));text-align:center;padding:48px 20px 28px}
#snooze-glossary .gl-crumb{font-size:.85rem;color:var(--c-muted);margin-bottom:14px}
#snooze-glossary .gl-crumb a{color:var(--c-coral)}#snooze-glossary .gl-crumb span{margin:0 6px;color:var(--c-sage)}
#snooze-glossary .gl-hero h1{font-size:clamp(2.1rem,5vw,3.4rem)}
#snooze-glossary .gl-intro{max-width:680px;margin:14px auto 24px;font-size:1.08rem;color:var(--c-muted)}
#snooze-glossary .gl-search{position:relative;max-width:520px;margin:0 auto 18px}
#snooze-glossary .gl-search input{width:100%;padding:14px 20px 14px 46px;font:inherit;font-size:1rem;color:var(--c-text);background:var(--c-white);border:1px solid rgba(15,23,42,.12);border-radius:50px;box-shadow:var(--shadow)}
#snooze-glossary .gl-search input:focus{outline:none;border-color:var(--c-coral);box-shadow:0 0 0 4px rgba(244,51,87,.16)}
#snooze-glossary .gl-search i{position:absolute;left:18px;top:50%;transform:translateY(-50%);color:var(--c-sage)}
#snooze-glossary .gl-cats{display:flex;flex-wrap:wrap;justify-content:center;gap:8px}
#snooze-glossary .gl-cat-pill{font:inherit;font-size:.88rem;font-weight:600;color:var(--c-navy);background:var(--c-white);border:1px solid rgba(15,23,42,.12);border-radius:50px;padding:8px 16px;cursor:pointer;transition:.2s}
#snooze-glossary .gl-cat-pill:hover{border-color:var(--c-coral);color:var(--c-coral)}
#snooze-glossary .gl-cat-pill.is-active{background:var(--c-coral);border-color:var(--c-coral);color:#fff}
#snooze-glossary .gl-az{position:sticky;top:0;z-index:20;display:flex;flex-wrap:nowrap;justify-content:center;gap:2px;overflow-x:auto;padding:10px 12px;background:rgba(255,255,255,.92);backdrop-filter:blur(6px);border-bottom:1px solid rgba(15,23,42,.08)}
#snooze-glossary .gl-az a,#snooze-glossary .gl-az span{flex:0 0 auto;min-width:26px;text-align:center;font-size:.82rem;font-weight:700;padding:5px 0;border-radius:6px;color:var(--c-navy)}
#snooze-glossary .gl-az a:hover{background:var(--c-coral);color:#fff}
#snooze-glossary .gl-az .is-off{color:#cbd5e1;pointer-events:none}
#snooze-glossary .gl-list{max-width:820px;margin:0 auto;padding:8px 20px 24px}
#snooze-glossary .gl-noresults{text-align:center;color:var(--c-muted);padding:40px 0}
#snooze-glossary .gl-lg{margin-top:18px}
#snooze-glossary .gl-letter{font-size:1.6rem;color:var(--c-coral);padding:10px 0 8px;border-bottom:2px solid rgba(244,51,87,.18);margin-bottom:14px;scroll-margin-top:64px}
#snooze-glossary .gl-term{background:var(--c-white);border:1px solid rgba(15,23,42,.07);border-left:4px solid var(--c-coral);border-radius:12px;padding:18px 22px;margin-bottom:12px;scroll-margin-top:64px}
#snooze-glossary .gl-head{display:flex;align-items:center;gap:12px}
#snooze-glossary .gl-name{font-family:var(--fh);font-size:1.3rem;font-weight:600;color:var(--c-navy);flex:1 1 auto}
#snooze-glossary .gl-tag{flex:0 0 auto;font-size:.72rem;font-weight:600;color:var(--c-navy);background:rgba(124,138,152,.16);border-radius:50px;padding:4px 11px;cursor:pointer;white-space:nowrap}
#snooze-glossary .gl-tag:hover{background:rgba(124,138,152,.3)}
#snooze-glossary .gl-def{font-size:1.02rem;font-weight:500;color:var(--c-text);margin:10px 0 0}
#snooze-glossary .gl-more{display:none;margin-top:14px;padding-top:14px;border-top:1px solid rgba(15,23,42,.07)}
#snooze-glossary .gl-term.is-open .gl-more{display:block}
#snooze-glossary .gl-context{color:var(--c-muted);margin:0 0 14px}
#snooze-glossary .gl-related{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:0 0 14px}
#snooze-glossary .gl-related-label{font-size:.8rem;font-weight:600;color:var(--c-sage);margin-right:2px}
#snooze-glossary .gl-chip{font-size:.82rem;font-weight:500;color:var(--c-coral-hover);background:rgba(244,51,87,.08);border-radius:50px;padding:5px 12px}
#snooze-glossary .gl-chip:hover{background:rgba(244,51,87,.18)}
#snooze-glossary .gl-cta{display:inline-block;font-size:.92rem;font-weight:600;color:var(--c-coral)}
#snooze-glossary .gl-cta i{font-size:.78rem;margin-left:4px}
#snooze-glossary .gl-cta:hover{color:var(--c-coral-hover)}
#snooze-glossary .gl-foot{display:flex;justify-content:flex-end;margin-top:10px}
#snooze-glossary .gl-toggle{font:inherit;font-style:italic;font-size:.85rem;color:var(--c-coral);background:none;border:none;padding:0;cursor:pointer}
#snooze-glossary .gl-toggle:hover{color:var(--c-coral-hover);text-decoration:underline}
#snooze-glossary .gl-band{background:var(--c-beige);text-align:center;padding:56px 20px}
#snooze-glossary .gl-band h2{font-size:clamp(1.6rem,4vw,2.3rem)}
#snooze-glossary .gl-band p{max-width:640px;margin:14px auto 24px;color:var(--c-muted)}
#snooze-glossary .gl-band p.gl-cta-note{margin:16px auto 0;font-size:.9rem}
#snooze-glossary .gl-btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:14px 32px;background:var(--c-coral);color:#fff;font-weight:600;border-radius:50px;box-shadow:0 6px 18px rgba(244,51,87,.22)}
#snooze-glossary .gl-btn:hover{background:var(--c-coral-hover);transform:translateY(-2px);color:#fff}
@media(max-width:768px){#snooze-glossary .gl-name{font-size:1.15rem}#snooze-glossary .gl-term{padding:16px}#snooze-glossary .gl-az a,#snooze-glossary .gl-az span{min-width:22px}}

settings.js:
(function(){function init(){var root=document.getElementById('snooze-glossary');if(!root)return;
var search=root.querySelector('#gl-search-input');var terms=[].slice.call(root.querySelectorAll('.gl-term'));
var lgs=[].slice.call(root.querySelectorAll('.gl-lg'));var noRes=root.querySelector('#gl-noresults');var activeCat='all';
function apply(){var q=(search&&search.value.trim().toLowerCase())||'';var any=false;
terms.forEach(function(t){var okC=activeCat==='all'||t.getAttribute('data-cat')===activeCat;
var hay=(t.textContent+' '+(t.getAttribute('data-aliases')||'')).toLowerCase();var okS=q===''||hay.indexOf(q)!==-1;
var show=okC&&okS;t.hidden=!show;if(show)any=true;});
var present={};lgs.forEach(function(g){var v=g.querySelectorAll('.gl-term:not([hidden])').length;g.hidden=v===0;if(v)present[g.getAttribute('data-letter')]=1;});
root.querySelectorAll('.gl-az [data-letter]').forEach(function(el){el.classList.toggle('is-off',!present[el.getAttribute('data-letter')]);});
if(noRes)noRes.hidden=any;}
root.querySelectorAll('.gl-cat-pill').forEach(function(p){p.addEventListener('click',function(){activeCat=p.getAttribute('data-cat');
root.querySelectorAll('.gl-cat-pill').forEach(function(x){x.classList.toggle('is-active',x===p);});apply();});});
root.querySelectorAll('.gl-tag').forEach(function(tag){function go(e){e.stopPropagation();var c=tag.getAttribute('data-cat');
var pill=root.querySelector('.gl-cat-pill[data-cat="'+c+'"]');if(pill)pill.click();var h=root.querySelector('.gl-hero');if(h)h.scrollIntoView({behavior:'smooth'});}
tag.addEventListener('click',go);tag.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){go(e);}});});
if(search)search.addEventListener('input',apply);
terms.forEach(function(t){var b=t.querySelector('.gl-toggle');if(b)b.addEventListener('click',function(){var o=t.classList.toggle('is-open');b.textContent=o?'less...':'more...';b.setAttribute('aria-expanded',o?'true':'false');});});
function openHash(){var id=(location.hash||'').replace(/[^#\w-]/g,'');if(id.length>1){var el=root.querySelector(id);if(el&&el.classList&&el.classList.contains('gl-term')){el.classList.add('is-open');var b=el.querySelector('.gl-toggle');if(b){b.textContent='less...';b.setAttribute('aria-expanded','true');}}}}
root.querySelectorAll('.gl-chip').forEach(function(c){c.addEventListener('click',function(){setTimeout(openHash,0);});});
window.addEventListener('hashchange',openHash);openHash();
try{if(typeof window.SnoozeUserDetection!=='undefined'){var s=window.SnoozeUserDetection.getUserStatus();var slot=root.querySelector('#gl-cta-slot');
if(slot&&s==='snooze-member'){slot.innerHTML='<a href="'+(window.SNOOZE_LIBRARY_URL||'/snooze-library')+'" class="gl-btn">Go to your Library</a>';}}}catch(e){}}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();
